From 3efbb8ab9429c91ec92b5fa9604a4c163f144fe7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:07:08 +0100
Subject: [PATCH] applets/systemtray: offer tray settings in item menus when
 arrow is hidden

With nothing hidden, such as after enabling "Always show all entries", the
expander arrow disappears and with it the only obvious way to the System
Tray settings. Right-clicking a tray widget now also offers them then.

BUG: 449565
---
 applets/systemtray/qml/PlasmoidItem.qml | 2 +-
 applets/systemtray/systemtray.cpp       | 7 ++++++-
 applets/systemtray/systemtray.h         | 2 +-
 3 files changed, 8 insertions(+), 3 deletions(-)

diff --git a/applets/systemtray/qml/PlasmoidItem.qml b/applets/systemtray/qml/PlasmoidItem.qml
index bbefd007b5..383e4ec073 100644
--- a/applets/systemtray/qml/PlasmoidItem.qml
+++ b/applets/systemtray/qml/PlasmoidItem.qml
@@ -71,7 +71,7 @@ AbstractItem {
     onContextMenu: mouse => {
         if (applet) {
             effectivePressed = false;
-            Plasmoid.showPlasmoidMenu(applet, 0, inHiddenLayout ? applet.height : 0);
+            Plasmoid.showPlasmoidMenu(applet, 0, inHiddenLayout ? applet.height : 0, root.hiddenLayout.itemCount === 0);
         }
     }
     onWheel: wheel => {
diff --git a/applets/systemtray/systemtray.cpp b/applets/systemtray/systemtray.cpp
index 4c1db7a2e7..40b5a67408 100644
--- a/applets/systemtray/systemtray.cpp
+++ b/applets/systemtray/systemtray.cpp
@@ -258,7 +258,7 @@ void SystemTray::restoreContents(KConfigGroup &group)
     initRegistry();
 }

-void SystemTray::showPlasmoidMenu(QQuickItem *appletInterface, int x, int y)
+void SystemTray::showPlasmoidMenu(QQuickItem *appletInterface, int x, int y, bool showTrayConfigure)
 {
     if (!appletInterface) {
         return;
@@ -311,6 +311,11 @@ void SystemTray::showPlasmoidMenu(QQuickItem *appletInterface, int x, int y)
         desktopMenu->addAction(applet->internalAction(QStringLiteral("configure")));
     }

+    if (QAction *trayConfigure = internalAction(QStringLiteral("configure")); showTrayConfigure && trayConfigure) {
+        desktopMenu->addSeparator();
+        desktopMenu->addAction(trayConfigure);
+    }
+
     if (desktopMenu->isEmpty()) {
         delete desktopMenu;
         return;
diff --git a/applets/systemtray/systemtray.h b/applets/systemtray/systemtray.h
index 8f06cfadf6..419bf6161f 100644
--- a/applets/systemtray/systemtray.h
+++ b/applets/systemtray/systemtray.h
@@ -47,7 +47,7 @@ public:
     /**
      * Given an AppletInterface pointer, shows a proper context menu for it
      */
-    Q_INVOKABLE void showPlasmoidMenu(QQuickItem *appletInterface, int x, int y);
+    Q_INVOKABLE void showPlasmoidMenu(QQuickItem *appletInterface, int x, int y, bool showTrayConfigure = false);

     /**
      * Find out global coordinates for a popup given local MouseArea
-- 
2.53.0
